from dataflow.core import OperatorABC
from dataflow.utils.registry import OPERATOR_REGISTRY
import pandas as pd

@OPERATOR_REGISTRY.register()
class EcommerceStatusNormalizer(OperatorABC):
    @staticmethod
    def get_desc(lang='en'):
        return 'normalize categorical values while preserving unmatched values and all rows'
    def run(self, storage, input_key):
        df = storage.read('dataframe').copy()
        mapping = {'paid': 'paid', 'PAYED': 'paid', 'completed': 'paid', 'cancel': 'cancelled', 'cancelled': 'cancelled', 'canceled': 'cancelled'}
        df[input_key] = df[input_key].map(lambda value: mapping.get(value, value))
        storage.write(df)
        return [input_key]

from dataflow.core import OperatorABC
from dataflow.utils.registry import OPERATOR_REGISTRY
import pandas as pd

@OPERATOR_REGISTRY.register()
class NumericCoercionRefiner(OperatorABC):
    @staticmethod
    def get_desc(lang='en'):
        return 'convert dataframe column to numeric with invalid-value coercion and no row filtering'
    def run(self, storage, input_key):
        df = storage.read('dataframe').copy()
        df[input_key] = pd.to_numeric(df[input_key], errors='coerce')
        storage.write(df)
        return [input_key]

from dataflow.core import OperatorABC
from dataflow.utils.registry import OPERATOR_REGISTRY
import pandas as pd

@OPERATOR_REGISTRY.register()
class GenerateOrderLabelOperator(OperatorABC):
    @staticmethod
    def get_desc(lang='en'):
        return 'Generate order_label as valid_order when status equals paid and amount is greater than zero, preserving all rows'
    def run(self, storage, input_status_key, input_amount_key, output_key):
        df = storage.read('dataframe').copy()
        valid = (df[input_status_key] == 'paid') & (df[input_amount_key] > 0)
        df[output_key] = valid.map({True: 'valid_order', False: 'other_order'})
        storage.write(df)
        return [output_key]
